package main

import (
	"io"

	"github.com/spf13/cobra"
)

func writeCompletion(shell string, noDescriptions bool, out io.Writer) error {
	root := completionTree()
	switch shell {
	case "bash":
		return root.GenBashCompletionV2(out, !noDescriptions)
	case "fish":
		return root.GenFishCompletion(out, !noDescriptions)
	case "powershell":
		return root.GenPowerShellCompletionWithDesc(out)
	case "zsh":
		return root.GenZshCompletion(out)
	default:
		return nil
	}
}

func completionTree() *cobra.Command {
	root := &cobra.Command{Use: "atlas", Short: "Manage your database schema as code"}
	root.AddCommand(
		&cobra.Command{Use: "completion", Short: "Generate the autocompletion script for the specified shell"},
		&cobra.Command{Use: "help", Short: "Help about any command"},
		&cobra.Command{Use: "license", Short: "Display license information"},
		&cobra.Command{Use: "version", Short: "Prints this Atlas CLI version information."},
	)
	schema := &cobra.Command{Use: "schema", Short: "Work with atlas schemas."}
	schema.AddCommand(
		&cobra.Command{Use: "apply", Short: "Apply an atlas schema to a target database."},
		&cobra.Command{Use: "clean", Short: "Removes all objects from the connected database."},
		&cobra.Command{Use: "diff", Short: "Calculate and print the diff between two schemas."},
		&cobra.Command{Use: "fmt", Short: "Formats Atlas HCL files"},
		&cobra.Command{Use: "inspect", Short: "Inspect a database and print its schema in Atlas DDL syntax."},
	)
	migrate := &cobra.Command{Use: "migrate", Short: "Manage versioned migration files"}
	migrate.AddCommand(
		&cobra.Command{Use: "apply", Short: "Applies pending migration files on the connected database."},
		&cobra.Command{Use: "diff", Short: "Compute the diff between the migration directory and a desired state and create a new migration file."},
		&cobra.Command{Use: "hash", Short: "Hash (re-)creates an integrity hash file for the migration directory."},
		&cobra.Command{Use: "import", Short: "Import a migration directory from another migration management tool to the Atlas format."},
		&cobra.Command{Use: "lint", Short: "Run analysis on the migration directory"},
		&cobra.Command{Use: "new", Short: "Creates a new empty migration file in the migration directory."},
		&cobra.Command{Use: "set", Short: "Set the current version of the migration history table."},
		&cobra.Command{Use: "status", Short: "Get information about the current migration status."},
		&cobra.Command{Use: "validate", Short: "Validates the migration directories checksum and SQL statements."},
	)
	root.AddCommand(schema, migrate)
	return root
}

/workspace/config.go.content:
package main

import (
	"fmt"
	"net/url"
	"os"
	"sort"
	"strings"

	"github.com/hashicorp/hcl/v2"
	"github.com/hashicorp/hcl/v2/hclparse"
	"github.com/hashicorp/hcl/v2/hclsyntax"
	"github.com/zclconf/go-cty/cty"
	"github.com/zclconf/go-cty/cty/function"
)

type globalFlags struct {
	configURL string
	env       string
	vars      map[string]string
}

type envConfig struct {
	values map[string]cty.Value
}

type namedAttr struct {
	name string
	attr *hclsyntax.Attribute
}

func defaultGlobals() globalFlags {
	return globalFlags{
		configURL: "file://atlas.hcl",
		vars:      map[string]string{},
	}
}

func parseConfigPath(raw string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return "", fmt.Errorf("invalid config file url: %w", err)
	}
	if u.Scheme == "" {
		return "", fmt.Errorf("missing scheme for config file. Did you mean %s?", "file://"+raw)
	}
	if u.Scheme != "file" {
		return "", fmt.Errorf("unsupported config file scheme %q", u.Scheme)
	}
	path := u.Host + u.Path
	if path == "" {
		return "", nil
	}
	return path, nil
}

func parseDirURL(raw string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return "", fmt.Errorf("invalid dir url: %w", err)
	}
	if u.Scheme == "" {
		return "", fmt.Errorf("missing scheme for dir url. Did you mean %q? ", "file://"+raw)
	}
	if u.Scheme != "file" {
		return "", fmt.Errorf("unsupported dir url scheme %q", u.Scheme)
	}
	path := u.Host + u.Path
	return path, nil
}

func loadEnvConfig(globals globalFlags) (*envConfig, error) {
	path, err := parseConfigPath(globals.configURL)
	if err != nil {
		return nil, err
	}
	data, readErr := os.ReadFile(path)
	if readErr != nil {
		return nil, fmt.Errorf("config file %q was not found: %w", path, readErr)
	}
	parser := hclparse.NewParser()
	file, diags := parser.ParseHCL(data, path)
	if diags.HasErrors() {
		return nil, fmt.Errorf(strings.TrimSpace(diags.Error()))
	}
	body, ok := file.Body.(*hclsyntax.Body)
	if !ok {
		return nil, fmt.Errorf("invalid config body")
	}
	var envBlock *hclsyntax.Block
	varBlocks := []*hclsyntax.Block{}
	localAttrs := []namedAttr{}
	for _, block := range body.Blocks {
		switch block.Type {
		case "variable":
			varBlocks = append(varBlocks, block)
		case "locals":
			localAttrs = append(localAttrs, orderedAttrs(block.Body)...)
		case "env":
			if len(block.Labels) > 0 && block.Labels[0] == globals.env {
				envBlock = block
			}
		}
	}
	if envBlock == nil {
		return nil, fmt.Errorf("env %q not defined in config file", globals.env)
	}
	varsResolved := map[string]cty.Value{}
	for _, block := range varBlocks {
		if len(block.Labels) == 0 {
			continue
		}
		name := block.Labels[0]
		if value, ok := globals.vars[name]; ok {
			varsResolved[name] = cty.StringVal(value)
			continue
		}
		attr := block.Body.Attributes["default"]
		if attr == nil {
			return nil, fmt.Errorf("missing value for required variable %q", name)
		}
		ctx := newEvalContext(varsResolved, nil, globals.env)
		value, diags := attr.Expr.Value(ctx)
		if diags.HasErrors() {
			return nil, fmt.Errorf(strings.TrimSpace(diags.Error()))
		}
		varsResolved[name] = value
	}
	sort.Slice(localAttrs, func(i, j int) bool {
		return localAttrs[i].attr.Range().Start.Byte < localAttrs[j].attr.Range().Start.Byte
	})
	localsResolved := map[string]cty.Value{}
	for _, attr := range localAttrs {
		ctx := newEvalContext(varsResolved, localsResolved, globals.env)
		value, diags := attr.attr.Expr.Value(ctx)
		if diags.HasErrors() {
			return nil, fmt.Errorf(strings.TrimSpace(diags.Error()))
		}
		localsResolved[attr.name] = value
	}
	envAttrs := orderedAttrs(envBlock.Body)
	sort.Slice(envAttrs, func(i, j int) bool {
		return envAttrs[i].attr.Range().Start.Byte < envAttrs[j].attr.Range().Start.Byte
	})
	values := map[string]cty.Value{}
	for _, attr := range envAttrs {
		ctx := newEvalContext(varsResolved, localsResolved, globals.env)
		value, diags := attr.attr.Expr.Value(ctx)
		if diags.HasErrors() {
			return nil, fmt.Errorf(strings.TrimSpace(diags.Error()))
		}
		values[attr.name] = value
	}
	return &envConfig{values: values}, nil
}

func orderedAttrs(body *hclsyntax.Body) []namedAttr {
	out := make([]namedAttr, 0, len(body.Attributes))
	for name, attr := range body.Attributes {
		out = append(out, namedAttr{name: name, attr: attr})
	}
	return out
}

func newEvalContext(vars map[string]cty.Value, locals map[string]cty.Value, envName string) *hcl.EvalContext {
	ctx := &hcl.EvalContext{
		Variables: map[string]cty.Value{},
		Functions: map[string]function.Function{
			"getenv": function.New(&function.Spec{
				Params: []function.Parameter{
					{Name: "key", Type: cty.String},
				},
				Type: function.StaticReturnType(cty.String),
				Impl: func(args []cty.Value, _ cty.Type) (cty.Value, error) {
					return cty.StringVal(os.Getenv(args[0].AsString())), nil
				},
			}),
		},
	}
	if len(vars) > 0 {
		ctx.Variables["var"] = cty.ObjectVal(vars)
	}
	if len(locals) > 0 {
		ctx.Variables["local"] = cty.ObjectVal(locals)
	}
	ctx.Variables["atlas"] = cty.ObjectVal(map[string]cty.Value{
		"env": cty.StringVal(envName),
	})
	return ctx
}

func valueAsString(values map[string]cty.Value, key string) string {
	value, ok := values[key]
	if !ok {
		return ""
	}
	if value.Type() == cty.String {
		return value.AsString()
	}
	return ""
}

