	"atlasreimpl/cmdlog"

	"github.com/hashicorp/hcl/v2/hclwrite"
	_ "modernc.org/sqlite"
)

type inspectOptions struct {
	globals globalFlags
	url     string
	format  string
}

func runSchema(args []string) int {
	globals, rest, help, err := parseLeadingGlobals(args)
	if err != nil {
		return printError(err.Error())
	}
	if help || len(rest) == 0 {
		printText(schemaHelp)
		return 0
	}
	switch rest[0] {
	case "apply":
		return runSchemaApply(rest[1:], globals)
	case "clean":
		return runSchemaClean(rest[1:], globals)
	case "diff":
		return runSchemaDiff(rest[1:], globals)
	case "fmt":
		return runSchemaFmt(rest[1:], globals)
	case "inspect":
		return runSchemaInspect(rest[1:], globals)
	default:
		printText(schemaHelp)
		return 0
	}
}

func runSchemaApply(args []string, globals globalFlags) int {
	if hasHelpFlag(args) {
		printText(schemaApplyHelp)
		return 0
	}
	_ = globals
	for i := 0; i < len(args); i++ {
		if isGlobalFlag(args[i]) {
			var err error
			globals, i, err = parseGlobalAt(args, i, globals)
			if err != nil {
				return printError(err.Error())
			}
			continue
		}
		if strings.HasPrefix(args[i], "-") {
			switch {
			case args[i] == "-u" || args[i] == "--url":
				i++
			case strings.HasPrefix(args[i], "--url="):
			default:
				return printError("unknown flag: " + args[i])
			}
		}
	}
	return printError(`required flag(s) "url" not set`)
}

func runSchemaClean(args []string, globals globalFlags) int {
	if hasHelpFlag(args) {
		printText(schemaCleanHelp)
		return 0
	}
	_ = globals
	return printError(`required flag(s) "url" not set`)
}

func runSchemaDiff(args []string, globals globalFlags) int {
	if hasHelpFlag(args) {
		printText(schemaDiffHelp)
		return 0
	}
	_ = globals
	return printError(`required flag(s) "from", "to" not set`)
}

func runSchemaFmt(args []string, globals globalFlags) int {
	if hasHelpFlag(args) {
		printText(schemaFmtHelp)
		return 0
	}
	_ = globals
	paths := []string{}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case isGlobalFlag(arg):
			var err error
			globals, i, err = parseGlobalAt(args, i, globals)
			if err != nil {
				return printError(err.Error())
			}
		case strings.HasPrefix(arg, "-"):
			return printError("unknown flag: " + arg)
		default:
			paths = append(paths, arg)
		}
	}
	if len(paths) == 0 {
		paths = []string{"."}
	}
	for _, path := range paths {
		if err := formatPath(path); err != nil {
			return printError(err.Error())
		}
	}
	return 0
}

func formatPath(path string) error {
	info, err := os.Stat(path)
	if err != nil {
		return fmt.Errorf("stat %s: %w", path, err)
	}
	if info.IsDir() {
		entries, err := os.ReadDir(path)
		if err != nil {
			return err
		}
		sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
		for _, entry := range entries {
			if entry.IsDir() || filepath.Ext(entry.Name()) != ".hcl" {
				continue
			}
			target := filepath.Join(path, entry.Name())
			changed, err := formatFile(target)
			if err != nil {
				return err
			}
			if changed {
				fmt.Fprintln(os.Stdout, target)
			}
		}
		return nil
	}
	if filepath.Ext(path) != ".hcl" {
		return nil
	}
	changed, err := formatFile(path)
	if err != nil {
		return err
	}
	if changed {
		fmt.Fprintln(os.Stdout, path)
	}
	return nil
}

func formatFile(path string) (bool, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return false, err
	}
	formatted := hclwrite.Format(data)
	if bytes.Equal(data, formatted) {
		return false, nil
	}
	return true, os.WriteFile(path, formatted, 0o644)
}

func runSchemaInspect(args []string, globals globalFlags) int {
	if hasHelpFlag(args) {
		printText(schemaInspectHelp)
		return 0
	}
	opts := inspectOptions{globals: globals}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "-u" || arg == "--url":
			i++
			if i >= len(args) {
				return printError("flag needs an argument: " + arg)
			}
			opts.url = args[i]
		case strings.HasPrefix(arg, "--url="):
			opts.url = strings.TrimPrefix(arg, "--url=")
		case arg == "--format":
			i++
			if i >= len(args) {
				return printError("flag needs an argument: --format")
			}
			opts.format = args[i]
		case strings.HasPrefix(arg, "--format="):
			opts.format = strings.TrimPrefix(arg, "--format=")
		case arg == "--dev-url":
			i++
		case strings.HasPrefix(arg, "--dev-url="):
		case arg == "-s" || arg == "--schema":
			i++
		case strings.HasPrefix(arg, "--schema="):
		case arg == "--exclude":
			i++
		case strings.HasPrefix(arg, "--exclude="):
		case isGlobalFlag(arg):
			var err error
			opts.globals, i, err = parseGlobalAt(args, i, opts.globals)
			if err != nil {
				return printError(err.Error())
			}
		case strings.HasPrefix(arg, "-"):
			return printError("unknown flag: " + arg)
		}
	}
	if opts.globals.env != "" {
		cfg, err := loadEnvConfig(opts.globals)
		if err != nil {
			return printError(err.Error())
		}
		if opts.url == "" {
			opts.url = valueAsString(cfg.values, "url")
		}
	}
	if opts.url == "" {
		return printError(`required flag(s) "url" not set`)
	}
	if !strings.Contains(opts.url, "://") {
		return printError("missing scheme. See: https://atlasgo.io/url")
	}
	inspect, err := inspectSQLite(opts.url)
	if err != nil {
		return printError(err.Error())
	}
	output, err := renderInspect(inspect, opts.format)
	if err != nil {
		return printError(err.Error())
	}
	fmt.Fprint(os.Stdout, output)
	return 0
}

func inspectSQLite(rawURL string) (*cmdlog.SchemaInspect, error) {
	if !strings.HasPrefix(rawURL, "sqlite://") {
		return nil, fmt.Errorf("sql/sqlclient: missing driver. See: https://atlasgo.io/url")
	}
	dsn := strings.TrimPrefix(rawURL, "sqlite://")
	if strings.HasPrefix(dsn, "/") && !strings.HasPrefix(dsn, "file:") {
		// Keep absolute paths as-is.
	} else if dsn == "" {
		return nil, fmt.Errorf("sql/sqlclient: missing driver. See: https://atlasgo.io/url")
	}
	if _, err := url.Parse(rawURL); err != nil {
		return nil, err
	}
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, err
	}
	defer db.Close()
	rows, err := db.Query(`SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY rowid`)
	if err != nil {
		return nil, fmt.Errorf("sqlite: querying schemas: %w", err)
	}
	defer rows.Close()
	schema := cmdlog.Schema{Name: "main"}
	for rows.Next() {
		var tableName string
		if err := rows.Scan(&tableName); err != nil {
			return nil, err
		}
		table, err := inspectSQLiteTable(db, tableName)
		if err != nil {
			return nil, err
		}
		schema.Tables = append(schema.Tables, *table)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return &cmdlog.SchemaInspect{
		Schemas: []cmdlog.Schema{schema},
	}, nil
}

func inspectSQLiteTable(db *sql.DB, tableName string) (*cmdlog.Table, error) {
	rows, err := db.Query(`PRAGMA table_info(` + quoteSQLiteIdent(tableName) + `)`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	table := &cmdlog.Table{Name: tableName}
	type pkCol struct {
		pos  int
		name string
	}
	pks := []pkCol{}
	for rows.Next() {
		var cid int
		var name string
		var typ string
		var notnull int
		var def sql.NullString
		var pk int
		if err := rows.Scan(&cid, &name, &typ, &notnull, &def, &pk); err != nil {
			return nil, err
		}
		col := cmdlog.Column{
			Name: name,
			Type: strings.ToUpper(typ),
			Null: notnull == 0,
		}
		table.Columns = append(table.Columns, col)
		if pk > 0 {
			pks = append(pks, pkCol{pos: pk, name: name})
		}
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	if len(pks) > 0 {
		sort.Slice(pks, func(i, j int) bool { return pks[i].pos < pks[j].pos })
		pk := &cmdlog.PrimaryKey{}
		for _, part := range pks {
			pk.Parts = append(pk.Parts, cmdlog.PrimaryKeyPart{Column: part.name})
		}
		table.PrimaryKey = pk
	}
	return table, nil
}

func quoteSQLiteIdent(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "''") + "'"
}

func renderInspect(inspect *cmdlog.SchemaInspect, format string) (string, error) {
	if format == "" {
		return renderInspectHCL(inspect), nil
	}
	funcs := template.FuncMap{
		"json": func(v any) (string, error) {
			data, err := json.Marshal(v)
			return string(data), err
		},
		"sql": func(v any, indent ...string) (string, error) {
			parsed, ok := v.(*cmdlog.SchemaInspect)
			if !ok {
				return "", fmt.Errorf("unexpected value")
			}
			if len(indent) > 0 {
				return renderInspectSQL(parsed, indent[0]), nil
			}
			return renderInspectSQL(parsed, ""), nil
		},
	}
	tmpl, err := template.New("format").Funcs(funcs).Parse(format)
	if err != nil {
		return "", fmt.Errorf("parse log format: %w", err)
	}
	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, inspect); err != nil {
		return "", err
	}
	return buf.String(), nil
}

func renderInspectHCL(inspect *cmdlog.SchemaInspect) string {
	if len(inspect.Schemas) == 0 {
		return ""
	}
	schema := inspect.Schemas[0]
	var b strings.Builder
	for _, table := range schema.Tables {
		fmt.Fprintf(&b, "table %q {\n", table.Name)
		b.WriteString("  schema = schema.main\n")
		for _, column := range table.Columns {
			fmt.Fprintf(&b, "  column %q {\n", column.Name)
			fmt.Fprintf(&b, "    null = %t\n", column.Null)
			fmt.Fprintf(&b, "    type = %s\n", strings.ToLower(column.Type))
			b.WriteString("  }\n")
		}
		if table.PrimaryKey != nil {
			b.WriteString("  primary_key {\n")
			b.WriteString("    columns = [")
			for i, part := range table.PrimaryKey.Parts {
				if i > 0 {
					b.WriteString(", ")
				}
				b.WriteString("column.")
				b.WriteString(part.Column)
			}
			b.WriteString("]\n")
			b.WriteString("  }\n")
		}
		b.WriteString("}\n")
	}
	fmt.Fprintf(&b, "schema %q {\n}\n", schema.Name)
	return b.String()
}

func renderInspectSQL(inspect *cmdlog.SchemaInspect, indent string) string {
	if len(inspect.Schemas) == 0 {
		return ""
	}
	var lines []string
	for _, table := range inspect.Schemas[0].Tables {
		lines = append(lines, fmt.Sprintf("-- Create %q table", table.Name))
		if indent == "" {
			var cols []string
			for _, column := range table.Columns {
				nullability := "NULL"
				if !column.Null {
					nullability = "NOT NULL"
				}
				cols = append(cols, fmt.Sprintf("`%s` %s %s", column.Name, strings.ToLower(column.Type), nullability))
			}
			if table.PrimaryKey != nil {
				var parts []string
				for _, part := range table.PrimaryKey.Parts {
					parts = append(parts, fmt.Sprintf("`%s`", part.Column))
				}
				cols = append(cols, "PRIMARY KEY ("+strings.Join(parts, ", ")+")")
			}
			lines = append(lines, fmt.Sprintf("CREATE TABLE `%s` (%s);", table.Name, strings.Join(cols, ", ")))
			continue
		}
		lines = append(lines, fmt.Sprintf("CREATE TABLE `%s` (", table.Name))
		var cols []string
		for _, column := range table.Columns {
			nullability := "NULL"
			if !column.Null {
				nullability = "NOT NULL"
			}
			cols = append(cols, fmt.Sprintf("%s`%s` %s %s", indent, column.Name, strings.ToLower(column.Type), nullability))
		}
		if table.PrimaryKey != nil {
			var parts []string
			for _, part := range table.PrimaryKey.Parts {
				parts = append(parts, fmt.Sprintf("`%s`", part.Column))
			}
			cols = append(cols, fmt.Sprintf("%sPRIMARY KEY (%s)", indent, strings.Join(parts, ", ")))
		}
		lines = append(lines, strings.Join(cols, ",\n"))
		lines = append(lines, ");")
	}
	return strings.Join(lines, "\n")
}

