package main

import (
	"fmt"
	"os"
	"strings"
)

func main() {
	os.Exit(run(os.Args[1:]))
}

func run(args []string) int {
	if len(args) == 0 {
		printText(rootHelp)
		return 0
	}
	switch args[0] {
	case "-h", "--help":
		printText(rootHelp)
		return 0
	case "--version":
		fmt.Fprintln(os.Stderr, "Error: unknown flag: --version")
		fmt.Fprintln(os.Stderr, "You're running the community build of Atlas, which may differ from the official version.")
		fmt.Fprintln(os.Stderr, "If this error persists, try installing the official version as a troubleshooting step:")
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, "  curl -sSf https://atlasgo.sh | sh")
		fmt.Fprintln(os.Stderr)
		fmt.Fprintln(os.Stderr, "More installation options: https://atlasgo.io/docs#installation")
		return 1
	}
	if strings.HasPrefix(args[0], "-") {
		return printError("unknown flag: " + args[0])
	}
	switch args[0] {
	case "completion":
		return runCompletion(args[1:])
	case "help":
		return runHelp(args[1:])
	case "license":
		return runLeaf(args[1:], licenseHelp, licenseOutput)
	case "migrate":
		return runMigrate(args[1:])
	case "schema":
		return runSchema(args[1:])
	case "version":
		return runLeaf(args[1:], versionHelp, versionOutput)
	default:
		fmt.Fprintf(os.Stderr, "Error: unknown command %q for %q\n", args[0], "atlas")
		fmt.Fprintln(os.Stderr, "Run 'atlas --help' for usage.")
		return 1
	}
}

func runLeaf(args []string, helpText, output string) int {
	if hasHelpFlag(args) {
		printText(helpText)
		return 0
	}
	for _, arg := range args {
		if strings.HasPrefix(arg, "-") {
			return printError("unknown flag: " + arg)
		}
	}
	printText(output)
	return 0
}

func runCompletion(args []string) int {
	if len(args) == 0 || hasOnlyHelp(args) {
		printText(completionHelp)
		return 0
	}
	switch args[0] {
	case "bash":
		return runCompletionShell(args[1:], "bash", completionBashHelp)
	case "fish":
		return runCompletionShell(args[1:], "fish", completionFishHelp)
	case "powershell":
		return runCompletionShell(args[1:], "powershell", completionPowershellHelp)
	case "zsh":
		return runCompletionShell(args[1:], "zsh", completionZshHelp)
	default:
		printText(completionHelp)
		return 0
	}
}

func runCompletionShell(args []string, shell, helpText string) int {
	noDescriptions := false
	if hasHelpFlag(args) {
		printText(helpText)
		return 0
	}
	for _, arg := range args {
		switch arg {
		case "--no-descriptions":
			noDescriptions = true
		default:
			if strings.HasPrefix(arg, "-") {
				return printError("unknown flag: " + arg)
			}
		}
	}
	if err := writeCompletion(shell, noDescriptions, os.Stdout); err != nil {
		return printError(err.Error())
	}
	return 0
}

func runHelp(args []string) int {
	if len(args) == 0 || hasOnlyHelp(args) {
		printText(rootHelp)
		return 0
	}
	text, unknownRoot := resolveHelp(args)
	if unknownRoot {
		fmt.Fprintf(os.Stdout, "Unknown help topic [%s]\n", backtickArgs(args))
		printText(rootUnknownHelp)
		return 0
	}
	printText(text)
	return 0
}

func resolveHelp(args []string) (string, bool) {
	switch args[0] {
	case "completion":
		if len(args) == 1 {
			return completionHelp, false
		}
		switch args[1] {
		case "bash":
			return completionBashHelp, false
		case "fish":
			return completionFishHelp, false
		case "powershell":
			return completionPowershellHelp, false
		case "zsh":
			return completionZshHelp, false
		default:
			return completionHelp, false
		}
	case "help":
		return helpHelp, false
	case "license":
		return licenseHelp, false
	case "migrate":
		if len(args) == 1 {
			return migrateHelp, false
		}
		switch args[1] {
		case "apply":
			return migrateApplyHelp, false
		case "diff":
			return migrateDiffHelp, false
		case "hash":
			return migrateHashHelp, false
		case "import":
			return migrateImportHelp, false
		case "lint":
			return migrateLintHelp, false
		case "new":
			return migrateNewHelp, false
		case "set":
			return migrateSetHelp, false
		case "status":
			return migrateStatusHelp, false
		case "validate":
			return migrateValidateHelp, false
		default:
			return migrateHelp, false
		}
	case "schema":
		if len(args) == 1 {
			return schemaHelp, false
		}
		switch args[1] {
		case "apply":
			return schemaApplyHelp, false
		case "clean":
			return schemaCleanHelp, false
		case "diff":
			return schemaDiffHelp, false
		case "fmt":
			return schemaFmtHelp, false
		case "inspect":
			return schemaInspectHelp, false
		default:
			return schemaHelp, false
		}
	case "version":
		return versionHelp, false
	default:
		return "", true
	}
}

func parseLeadingGlobals(args []string) (globalFlags, []string, bool, error) {
	globals := defaultGlobals()
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "-h" || arg == "--help":
			return globals, nil, true, nil
		case isGlobalFlag(arg):
			var err error
			globals, i, err = parseGlobalAt(args, i, globals)
			if err != nil {
				return globals, nil, false, err
			}
		case strings.HasPrefix(arg, "-"):
			return globals, nil, false, fmt.Errorf("unknown flag: %s", arg)
		default:
			return globals, args[i:], false, nil
		}
	}
	return globals, nil, false, nil
}

func parseGlobalAt(args []string, i int, globals globalFlags) (globalFlags, int, error) {
	arg := args[i]
	switch {
	case arg == "-c" || arg == "--config":
		if i+1 >= len(args) {
			return globals, i, fmt.Errorf("flag needs an argument: %s", arg)
		}
		globals.configURL = args[i+1]
		return globals, i + 1, nil
	case strings.HasPrefix(arg, "--config="):
		globals.configURL = strings.TrimPrefix(arg, "--config=")
		return globals, i, nil
	case arg == "--env":
		if i+1 >= len(args) {
			return globals, i, fmt.Errorf("flag needs an argument: --env")
		}
		globals.env = args[i+1]
		return globals, i + 1, nil
	case strings.HasPrefix(arg, "--env="):
		globals.env = strings.TrimPrefix(arg, "--env=")
		return globals, i, nil
	case arg == "--var":
		if i+1 >= len(args) {
			return globals, i, fmt.Errorf("flag needs an argument: --var")
		}
		key, value, err := splitVar(args[i+1])
		if err != nil {
			return globals, i, err
		}
		globals.vars[key] = value
		return globals, i + 1, nil
	case strings.HasPrefix(arg, "--var="):
		key, value, err := splitVar(strings.TrimPrefix(arg, "--var="))
		if err != nil {
			return globals, i, err
		}
		globals.vars[key] = value
		return globals, i, nil
	default:
		return globals, i, fmt.Errorf("unknown flag: %s", arg)
	}
}

func splitVar(raw string) (string, string, error) {
	parts := strings.SplitN(raw, "=", 2)
	if len(parts) != 2 {
		return "", "", fmt.Errorf("invalid argument %q for \"--var\" flag: variables must be format as key=value, got: %q", raw, raw)
	}
	return parts[0], parts[1], nil
}

func hasHelpFlag(args []string) bool {
	for _, arg := range args {
		if arg == "-h" || arg == "--help" {
			return true
		}
	}
	return false
}

func hasOnlyHelp(args []string) bool {
	return len(args) == 1 && hasHelpFlag(args)
}

func isGlobalFlag(arg string) bool {
	return arg == "-c" || arg == "--config" || strings.HasPrefix(arg, "--config=") ||
		arg == "--env" || strings.HasPrefix(arg, "--env=") ||
		arg == "--var" || strings.HasPrefix(arg, "--var=")
}

func printText(text string) {
	fmt.Fprint(os.Stdout, text)
}

func printError(message string) int {
	fmt.Fprintln(os.Stderr, "Error:", message)
	return 1
}

func backtickArgs(args []string) string {
	quoted := make([]string, 0, len(args))
	for _, arg := range args {
		quoted = append(quoted, "`"+arg+"`")
	}
	return strings.Join(quoted, " ")
}

