func collectMigrationEntries(dir string) ([]migrationEntry, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("sql/migrate: %w", err)
	}
	sqlNames := []string{}
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		if filepath.Ext(entry.Name()) == ".sql" {
			sqlNames = append(sqlNames, entry.Name())
		}
	}
	sort.Strings(sqlNames)
	stream := sha256.New()
	result := make([]migrationEntry, 0, len(sqlNames))
	for _, name := range sqlNames {
		data, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil {
			return nil, err
		}
		stream.Write([]byte(name))
		stream.Write(data)
		result = append(result, migrationEntry{
			Name: name,
			Hash: "h1:" + base64.StdEncoding.EncodeToString(stream.Sum(nil)),
		})
	}
	return result, nil
}

func renderMigrationSumLines(entries []migrationEntry) []string {
	headerHasher := sha256.New()
	for _, entry := range entries {
		headerHasher.Write([]byte(entry.Name))
		headerHasher.Write([]byte(entry.Hash))
	}
	lines := []string{"h1:" + base64.StdEncoding.EncodeToString(headerHasher.Sum(nil))}
	for _, entry := range entries {
		lines = append(lines, entry.Name+" "+entry.Hash)
	}
	return lines
}

func writeMigrationSum(dir string, entries []migrationEntry) error {
	lines := renderMigrationSumLines(entries)
	content := strings.Join(lines, "\n") + "\n"
	return os.WriteFile(filepath.Join(dir, "atlas.sum"), []byte(content), 0o644)
}

func readLines(path string) ([]string, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	lines := []string{}
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines, scanner.Err()
}

func equalStringSlices(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func compareMigrationLines(oldLines []string, current []migrationEntry) (int, string) {
	oldEntries := make([]migrationEntry, 0, len(oldLines))
	for _, line := range oldLines {
		parts := strings.SplitN(line, " ", 2)
		if len(parts) == 2 {
			oldEntries = append(oldEntries, migrationEntry{Name: parts[0], Hash: parts[1]})
		}
	}
	i, j := 0, 0
	for i < len(oldEntries) || j < len(current) {
		lineNo := min(i, j) + 2
		switch {
		case i >= len(oldEntries):
			return lineNo, current[j].Name + " was added"
		case j >= len(current):
			return lineNo, oldEntries[i].Name + " was removed"
		case oldEntries[i].Name == current[j].Name:
			if oldEntries[i].Hash != current[j].Hash {
				return lineNo, current[j].Name + " was edited"
			}
			i++
			j++
		case oldEntries[i].Name < current[j].Name:
			return lineNo, oldEntries[i].Name + " was removed"
		default:
			return lineNo, current[j].Name + " was added"
		}
	}
	return 2, "checksum mismatch"
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

