package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/hashicorp/hcl/v2/hclwrite"
	"golang.org/x/mod/sumdb/dirhash"
)

func runSchemaFmt(cmd interface{ OutOrStdout() any }, args []string) error {
	if len(args) == 0 {
		args = []string{"."}
	}
	var outWriter *os.File
	switch c := cmd.(type) {
	case interface{ OutOrStdout() any }:
		if w, ok := c.OutOrStdout().(*os.File); ok {
			outWriter = w
		}
	}
	if outWriter == nil {
		outWriter = os.Stdout
	}

	for _, arg := range args {
		info, err := os.Stat(arg)
		if err != nil {
			return err
		}
		if info.IsDir() {
			entries, err := os.ReadDir(arg)
			if err != nil {
				return err
			}
			sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
			for _, entry := range entries {
				if entry.IsDir() || filepath.Ext(entry.Name()) != ".hcl" {
					continue
				}
				path := filepath.Join(arg, entry.Name())
				changed, err := formatHCLFile(path)
				if err != nil {
					return err
				}
				if changed {
					fmt.Fprintln(outWriter, path)
				}
			}
			continue
		}
		if filepath.Ext(arg) != ".hcl" {
			continue
		}
		changed, err := formatHCLFile(arg)
		if err != nil {
			return err
		}
		if changed {
			fmt.Fprintln(outWriter, arg)
		}
	}
	return nil
}

func formatHCLFile(path string) (bool, error) {
	contents, err := os.ReadFile(path)
	if err != nil {
		return false, err
	}
	formatted := hclwrite.Format(contents)
	if string(formatted) == string(contents) {
		return false, nil
	}
	return true, os.WriteFile(path, formatted, 0o644)
}

func runMigrateHash(dirURL, dirFormat string) error {
	if dirFormat != "atlas" {
		return fmt.Errorf("unsupported migration dir format %q", dirFormat)
	}
	dirPath := fileURLPath(dirURL)
	if _, err := os.Stat(dirPath); err != nil {
		return fmt.Errorf("sql/migrate: stat %s: %w", dirPath, err)
	}
	sum, err := buildAtlasSum(dirPath)
	if err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(dirPath, "atlas.sum"), []byte(sum), 0o644)
}

func runMigrateNew(dirURL, dirFormat, name string, edit bool) error {
	if dirFormat != "atlas" {
		return fmt.Errorf("unsupported migration dir format %q", dirFormat)
	}
	dirPath := fileURLPath(dirURL)
	if err := os.MkdirAll(dirPath, 0o755); err != nil {
		return err
	}
	ts := time.Now().UTC().Format("20060102150405")
	fileName := ts + ".sql"
	if name != "" {
		fileName = ts + "_" + name + ".sql"
	}
	path := filepath.Join(dirPath, fileName)
	if err := os.WriteFile(path, nil, 0o644); err != nil {
		return err
	}
	sum, err := buildAtlasSum(dirPath)
	if err != nil {
		return err
	}
	if err := os.WriteFile(filepath.Join(dirPath, "atlas.sum"), []byte(sum), 0o644); err != nil {
		return err
	}
	if edit {
		return maybeEditFile(path)
	}
	return nil
}

func runMigrateValidate(dirURL, dirFormat, devURL string) error {
	if dirFormat != "atlas" {
		return fmt.Errorf("unsupported migration dir format %q", dirFormat)
	}
	_ = devURL
	dirPath := fileURLPath(dirURL)
	if _, err := os.Stat(dirPath); err != nil {
		return fmt.Errorf("sql/migrate: stat %s: %w", dirPath, err)
	}
	files, err := migrationFiles(dirPath)
	if err != nil {
		return err
	}
	sumPath := filepath.Join(dirPath, "atlas.sum")
	expected, err := os.ReadFile(sumPath)
	if err != nil {
		if os.IsNotExist(err) {
			if len(files) == 0 {
				return nil
			}
			fmt.Fprintln(os.Stderr, "You have a checksum error in your migration directory.")
			fmt.Fprintln(os.Stderr, "Please check your migration files and run 'atlas migrate hash' to re-hash the contents")
			return fmt.Errorf("checksum file not found")
		}
		return err
	}
	actual, err := buildAtlasSum(dirPath)
	if err != nil {
		return err
	}
	if string(expected) == actual {
		return nil
	}
	line, detail := checksumMismatchDetail(string(expected), actual)
	fmt.Fprintln(os.Stderr, "You have a checksum error in your migration directory.")
	fmt.Fprintln(os.Stderr)
	if detail != "" {
		fmt.Fprintf(os.Stderr, "\tL%d: %s\n", line, detail)
		fmt.Fprintln(os.Stderr)
	}
	fmt.Fprintln(os.Stderr, "Please check your migration files and run 'atlas migrate hash' to re-hash the contents")
	return fmt.Errorf("checksum mismatch")
}

func buildAtlasSum(dirPath string) (string, error) {
	files, err := migrationFiles(dirPath)
	if err != nil {
		return "", err
	}
	opener := func(name string) (io.ReadCloser, error) {
		return os.Open(filepath.Join(dirPath, name))
	}
	rootHash, err := dirhash.Hash1(files, opener)
	if err != nil {
		return "", err
	}
	lines := []string{rootHash}
	for _, name := range files {
		hash, err := dirhash.Hash1([]string{name}, opener)
		if err != nil {
			return "", err
		}
		lines = append(lines, fmt.Sprintf("%s %s", name, hash))
	}
	return strings.Join(lines, "\n") + "\n", nil
}

func migrationFiles(dirPath string) ([]string, error) {
	entries, err := os.ReadDir(dirPath)
	if err != nil {
		return nil, err
	}
	var files []string
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".sql" {
			continue
		}
		files = append(files, entry.Name())
	}
	sort.Strings(files)
	return files, nil
}

func checksumMismatchDetail(expected, actual string) (int, string) {
	expectedLines := manifestLines(expected)
	actualLines := manifestLines(actual)
	expectedEntries := parseManifestEntries(expectedLines)
	actualEntries := parseManifestEntries(actualLines)

	i := 0
	for i < len(expectedEntries) && i < len(actualEntries) {
		if expectedEntries[i].name != actualEntries[i].name {
			break
		}
		if expectedEntries[i].hash != actualEntries[i].hash {
			return expectedEntries[i].line, expectedEntries[i].name + " was edited"
		}
		i++
	}
	if i < len(expectedEntries) && i < len(actualEntries) {
		if !containsEntry(expectedEntries[i:].names(), actualEntries[i].name) {
			return actualEntries[i].line, actualEntries[i].name + " was added"
		}
		if !containsEntry(actualEntries[i:].names(), expectedEntries[i].name) {
			return expectedEntries[i].line, expectedEntries[i].name + " was removed"
		}
		return expectedEntries[i].line, expectedEntries[i].name + " was edited"
	}
	if i < len(expectedEntries) {
		return expectedEntries[i].line, expectedEntries[i].name + " was removed"
	}
	if i < len(actualEntries) {
		return actualEntries[i].line, actualEntries[i].name + " was added"
	}
	return 1, ""
}

type manifestEntry struct {
	line int
	name string
	hash string
}

func manifestLines(contents string) []string {
	scanner := bufio.NewScanner(strings.NewReader(contents))
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines
}

func parseManifestEntries(lines []string) []manifestEntry {
	var entries []manifestEntry
	for i := 1; i < len(lines); i++ {
		line := lines[i]
		idx := strings.LastIndex(line, " h1:")
		if idx < 0 {
			continue
		}
		entries = append(entries, manifestEntry{
			line: i + 1,
			name: line[:idx],
			hash: line[idx+1:],
		})
	}
	return entries
}

func (e []manifestEntry) names() []string {
	out := make([]string, 0, len(e))
	for _, entry := range e {
		out = append(out, entry.name)
	}
	return out
}

func containsEntry(names []string, target string) bool {
	for _, name := range names {
		if name == target {
			return true
		}
	}
	return false
}

