package main

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
	"text/template"

	"github.com/spf13/cobra"
)

type globalOptions struct {
	configURL string
	envName   string
	vars      []string
}

func newRootCmd() *cobra.Command {
	root := &cobra.Command{
		Use:   "atlas",
		Short: "Manage your database schema as code",
		Long:  "Manage your database schema as code",
		RunE: func(cmd *cobra.Command, args []string) error {
			return cmd.Help()
		},
	}
	root.Flags().SortFlags = false

	root.AddCommand(
		newCompletionCmd(),
		newLicenseCmd(),
		newMigrateCmd(),
		newSchemaCmd(),
		newVersionCmd(),
	)
	return root
}

func newVersionCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "version",
		Short: "Prints this Atlas CLI version information.",
		Run: func(cmd *cobra.Command, args []string) {
			fmt.Fprintln(cmd.OutOrStdout(), "atlas unofficial version - development")
			fmt.Fprintln(cmd.OutOrStdout(), "https://github.com/ariga/atlas/releases/latest")
			fmt.Fprintln(cmd.OutOrStdout(), "To download an official version, visit: https://atlasgo.io/getting-started#installation")
		},
