		}),
		newCompletionShellCmd("powershell", "Generate the autocompletion script for powershell", func(root, c *cobra.Command) error {
			return root.GenPowerShellCompletionWithDesc(c.OutOrStdout())
		}),
		newCompletionShellCmd("zsh", "Generate the autocompletion script for zsh", func(root, c *cobra.Command) error {
			return root.GenZshCompletion(c.OutOrStdout())
		}),
