func newSchemaCmd() *cobra.Command {
	opts := &globalOptions{}
	cmd := &cobra.Command{
		Use:   "schema [command]",
		Short: "Work with atlas schemas.",
		Long:  "The `atlas schema` command groups subcommands working with declarative Atlas schemas.",
		RunE: func(cmd *cobra.Command, args []string) error {
			return cmd.Help()
		},
	}
	cmd.PersistentFlags().SortFlags = false
	addGlobalFlags(cmd, opts)

	cmd.AddCommand(
		newSchemaApplyCmd(opts),
		newSchemaCleanCmd(opts),
		newSchemaDiffCmd(opts),
		newSchemaFmtCmd(opts),
		newSchemaInspectCmd(opts),
