package main

import (
	"fmt"
	"io"
)

func writeCompletion(shell string, noDescriptions bool, out io.Writer) error {
	_ = noDescriptions
	switch shell {
	case "bash":
		_, err := io.WriteString(out, bashCompletion)
		return err
	case "fish":
		_, err := io.WriteString(out, fishCompletion)
		return err
	case "powershell":
		_, err := io.WriteString(out, powershellCompletion)
		return err
	case "zsh":
		_, err := io.WriteString(out, zshCompletion)
		return err
	default:
		return fmt.Errorf("unsupported shell %q", shell)
	}
}

const bashCompletion = `# bash completion for atlas
_atlas()
{
    local cur prev words cword
    _init_completion || return

    local root="completion help license migrate schema version"
    local schema="apply clean diff fmt inspect"
    local migrate="apply diff hash import lint new set status validate"
    local completion="bash fish powershell zsh"

    if [[ ${cword} -eq 1 ]]; then
        COMPREPLY=( $(compgen -W "${root}" -- "${cur}") )
        return
    fi
    case "${words[1]}" in
        schema)
            COMPREPLY=( $(compgen -W "${schema}" -- "${cur}") )
            ;;
        migrate)
            COMPREPLY=( $(compgen -W "${migrate}" -- "${cur}") )
            ;;
        completion)
            COMPREPLY=( $(compgen -W "${completion}" -- "${cur}") )
            ;;
    esac
}

complete -F _atlas atlas
`

const fishCompletion = `complete -c atlas -f -a "completion help license migrate schema version"
complete -c atlas -n "__fish_seen_subcommand_from schema" -f -a "apply clean diff fmt inspect"
complete -c atlas -n "__fish_seen_subcommand_from migrate" -f -a "apply diff hash import lint new set status validate"
complete -c atlas -n "__fish_seen_subcommand_from completion" -f -a "bash fish powershell zsh"
`

const powershellCompletion = `Register-ArgumentCompleter -Native -CommandName atlas -ScriptBlock {
    param($wordToComplete, $commandAst, $cursorPosition)
    $words = $commandAst.CommandElements | ForEach-Object { $_.Extent.Text }
    $root = 'completion','help','license','migrate','schema','version'
    $schema = 'apply','clean','diff','fmt','inspect'
    $migrate = 'apply','diff','hash','import','lint','new','set','status','validate'
    $completion = 'bash','fish','powershell','zsh'
    if ($words.Count -le 2) {
        $root | Where-Object { $_ -like "$wordToComplete*" } | ForEach-Object {
            [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_)
        }
