package main

import (
	"bytes"
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

type valueKind int

const (
	valueString valueKind = iota
	valueBool
	valueList
)

type miniValue struct {
	kind valueKind
	s    string
	b    bool
	list []miniValue
}

func (v miniValue) String() string {
	switch v.kind {
	case valueBool:
		if v.b {
			return "true"
		}
		return "false"
	case valueList:
		parts := make([]string, 0, len(v.list))
		for _, item := range v.list {
			parts = append(parts, item.String())
		}
		return "[" + strings.Join(parts, ", ") + "]"
	default:
		return v.s
	}
}

type hclPos struct {
	Line   int
	Column int
	Offset int
}

type hclTokenKind int

const (
	tokenEOF hclTokenKind = iota
	tokenIdent
	tokenString
	tokenNumber
	tokenLBrace
	tokenRBrace
	tokenLBracket
	tokenRBracket
	tokenLParen
	tokenRParen
	tokenEqual
	tokenComma
	tokenDot
	tokenNewline
)

type hclToken struct {
	kind       hclTokenKind
	text       string
	start, end hclPos
}

type hclDiag struct {
	path    string
	start   hclPos
	end     hclPos
	summary string
	detail  string
}

func (d *hclDiag) Error() string {
	return fmt.Sprintf("%s:%d,%d-%d: %s; %s", d.path, d.start.Line, d.start.Column, d.end.Column, d.summary, d.detail)
}

type hclLexer struct {
	src        []rune
	idx        int
	line       int
	col        int
	keepNewline bool
}

func newHCLLexer(src string, keepNewline bool) *hclLexer {
	return &hclLexer{src: []rune(src), line: 1, col: 1, keepNewline: keepNewline}
}

func (l *hclLexer) pos() hclPos {
	return hclPos{Line: l.line, Column: l.col, Offset: l.idx}
}

func (l *hclLexer) peek() rune {
	if l.idx >= len(l.src) {
		return 0
	}
	return l.src[l.idx]
}

func (l *hclLexer) advance() rune {
	if l.idx >= len(l.src) {
		return 0
	}
	r := l.src[l.idx]
	l.idx++
	if r == '\n' {
		l.line++
		l.col = 1
	} else {
		l.col++
	}
	return r
}

func (l *hclLexer) nextToken() (hclToken, error) {
	for {
		r := l.peek()
		switch r {
		case 0:
			p := l.pos()
			return hclToken{kind: tokenEOF, start: p, end: p}, nil
		case ' ', '\t', '\r':
			l.advance()
		case '\n':
			start := l.pos()
			l.advance()
			if l.keepNewline {
				end := start
				end.Column++
				return hclToken{kind: tokenNewline, text: "\n", start: start, end: end}, nil
			}
		case '#':
			for r != 0 && r != '\n' {
				r = l.advance()
			}
		case '/':
			if l.idx+1 < len(l.src) && l.src[l.idx+1] == '/' {
				for r != 0 && r != '\n' {
					r = l.advance()
				}
				continue
			}
			return hclToken{}, fmt.Errorf("unexpected character /")
		default:
			start := l.pos()
			switch r {
			case '{':
				l.advance()
				end := l.pos()
				return hclToken{kind: tokenLBrace, text: "{", start: start, end: end}, nil
			case '}':
				l.advance()
				end := l.pos()
				return hclToken{kind: tokenRBrace, text: "}", start: start, end: end}, nil
			case '[':
				l.advance()
				end := l.pos()
				return hclToken{kind: tokenLBracket, text: "[", start: start, end: end}, nil
			case ']':
				l.advance()
				end := l.pos()
				return hclToken{kind: tokenRBracket, text: "]", start: start, end: end}, nil
			case '(':
				l.advance()
				end := l.pos()
				return hclToken{kind: tokenLParen, text: "(", start: start, end: end}, nil
			case ')':
				l.advance()
				end := l.pos()
				return hclToken{kind: tokenRParen, text: ")", start: start, end: end}, nil
			case '=':
				l.advance()
				end := l.pos()
				return hclToken{kind: tokenEqual, text: "=", start: start, end: end}, nil
			case ',':
				l.advance()
				end := l.pos()
				return hclToken{kind: tokenComma, text: ",", start: start, end: end}, nil
			case '.':
				l.advance()
				end := l.pos()
				return hclToken{kind: tokenDot, text: ".", start: start, end: end}, nil
			case '"':
				l.advance()
				var b strings.Builder
				for {
					ch := l.peek()
					if ch == 0 {
						return hclToken{}, fmt.Errorf("unterminated string")
					}
					if ch == '"' {
						l.advance()
						break
					}
					if ch == '\\' {
						l.advance()
						next := l.peek()
						if next == 0 {
							return hclToken{}, fmt.Errorf("unterminated string escape")
						}
						switch next {
						case '"', '\\', '/':
							b.WriteRune(next)
						case 'n':
							b.WriteByte('\n')
						case 't':
							b.WriteByte('\t')
						default:
							b.WriteRune(next)
						}
						l.advance()
						continue
					}
					b.WriteRune(ch)
					l.advance()
				}
				end := l.pos()
				return hclToken{kind: tokenString, text: b.String(), start: start, end: end}, nil
			default:
				if unicode.IsLetter(r) || r == '_' || r == '-' {
					var b strings.Builder
					for {
						ch := l.peek()
						if !(unicode.IsLetter(ch) || unicode.IsDigit(ch) || ch == '_' || ch == '-') {
							break
						}
						b.WriteRune(ch)
						l.advance()
					}
					end := l.pos()
					return hclToken{kind: tokenIdent, text: b.String(), start: start, end: end}, nil
				}
				if unicode.IsDigit(r) {
					var b strings.Builder
					for {
						ch := l.peek()
						if !unicode.IsDigit(ch) {
							break
						}
						b.WriteRune(ch)
						l.advance()
					}
					end := l.pos()
					return hclToken{kind: tokenNumber, text: b.String(), start: start, end: end}, nil
				}
				return hclToken{}, fmt.Errorf("unexpected character %q", r)
			}
		}
	}
}

func lexAllHCL(src string, keepNewline bool) ([]hclToken, error) {
	lexer := newHCLLexer(src, keepNewline)
	var tokens []hclToken
	for {
		tok, err := lexer.nextToken()
		if err != nil {
			return nil, err
		}
		tokens = append(tokens, tok)
		if tok.kind == tokenEOF {
			return tokens, nil
		}
	}
}

type expr interface {
	span() (hclPos, hclPos)
}

type identExpr struct {
	name       string
	start, end hclPos
}

func (e identExpr) span() (hclPos, hclPos) { return e.start, e.end }

type stringExpr struct {
	value      string
	start, end hclPos
}

func (e stringExpr) span() (hclPos, hclPos) { return e.start, e.end }

type traversalExpr struct {
	root       string
	parts      []string
	start, end hclPos
}

func (e traversalExpr) span() (hclPos, hclPos) { return e.start, e.end }

type callExpr struct {
	name       string
	args       []expr
	start, end hclPos
}

func (e callExpr) span() (hclPos, hclPos) { return e.start, e.end }

type listExpr struct {
	items      []expr
	start, end hclPos
}

func (e listExpr) span() (hclPos, hclPos) { return e.start, e.end }

type attrExpr struct {
	name string
	expr expr
	pos  hclToken
}

type blockExpr struct {
	typ   string
	label string
	attrs []attrExpr
}

type projectFile struct {
	blocks []blockExpr
}

type hclParser struct {
	path   string
	tokens []hclToken
	idx    int
}

func newHCLParser(path, src string) (*hclParser, error) {
	tokens, err := lexAllHCL(src, false)
	if err != nil {
		return nil, err
	}
	return &hclParser{path: path, tokens: tokens}, nil
}

func (p *hclParser) peek() hclToken {
	if p.idx >= len(p.tokens) {
		return p.tokens[len(p.tokens)-1]
	}
	return p.tokens[p.idx]
}

func (p *hclParser) next() hclToken {
	tok := p.peek()
	if p.idx < len(p.tokens) {
		p.idx++
	}
	return tok
}

func (p *hclParser) expect(kind hclTokenKind, summary, detail string) (hclToken, error) {
	tok := p.peek()
	if tok.kind != kind {
		return hclToken{}, &hclDiag{path: p.path, start: tok.start, end: tok.end, summary: summary, detail: detail}
	}
	p.idx++
	return tok, nil
}

func (p *hclParser) parseFile() (*projectFile, error) {
	file := &projectFile{}
	for p.peek().kind != tokenEOF {
		block, err := p.parseBlock()
		if err != nil {
			return nil, err
		}
		file.blocks = append(file.blocks, block)
	}
	return file, nil
}

func (p *hclParser) parseBlock() (blockExpr, error) {
	typeTok, err := p.expect(tokenIdent, "Argument or block definition required", "An argument or block definition is required here.")
	if err != nil {
		return blockExpr{}, err
	}
	block := blockExpr{typ: typeTok.text}
	if p.peek().kind == tokenString {
		block.label = p.next().text
	}
	if _, err := p.expect(tokenLBrace, "Argument or block definition required", "An argument or block definition is required here."); err != nil {
		return blockExpr{}, err
	}
	for p.peek().kind != tokenRBrace && p.peek().kind != tokenEOF {
		attr, err := p.parseAttr()
		if err != nil {
			return blockExpr{}, err
		}
		block.attrs = append(block.attrs, attr)
	}
	if _, err := p.expect(tokenRBrace, "Argument or block definition required", "An argument or block definition is required here."); err != nil {
		return blockExpr{}, err
	}
	return block, nil
}

func (p *hclParser) parseAttr() (attrExpr, error) {
	nameTok, err := p.expect(tokenIdent, "Argument or block definition required", "An argument or block definition is required here.")
	if err != nil {
		return attrExpr{}, err
	}
	if p.peek().kind != tokenEqual {
		tok := p.peek()
		return attrExpr{}, &hclDiag{
			path:    p.path,
			start:   tok.start,
			end:     tok.end,
			summary: "Argument or block definition required",
			detail:  "An argument or block definition is required here.",
		}
	}
	p.next()
	expression, err := p.parseExpr()
	if err != nil {
		return attrExpr{}, err
	}
	return attrExpr{name: nameTok.text, expr: expression, pos: nameTok}, nil
}

func (p *hclParser) parseExpr() (expr, error) {
	tok := p.peek()
	switch tok.kind {
	case tokenString:
		p.next()
		return stringExpr{value: tok.text, start: tok.start, end: tok.end}, nil
	case tokenNumber:
		p.next()
		return stringExpr{value: tok.text, start: tok.start, end: tok.end}, nil
	case tokenIdent:
		p.next()
		if p.peek().kind == tokenLParen {
			start := tok.start
			p.next()
			var args []expr
			for p.peek().kind != tokenRParen && p.peek().kind != tokenEOF {
				arg, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				args = append(args, arg)
				if p.peek().kind == tokenComma {
					p.next()
					continue
				}
				break
			}
			endTok, err := p.expect(tokenRParen, "Argument or block definition required", "An argument or block definition is required here.")
			if err != nil {
				return nil, err
			}
			return callExpr{name: tok.text, args: args, start: start, end: endTok.end}, nil
		}
		root := tok.text
		parts := []string{}
		end := tok.end
		for p.peek().kind == tokenDot {
			p.next()
			partTok, err := p.expect(tokenIdent, "Argument or block definition required", "An argument or block definition is required here.")
			if err != nil {
				return nil, err
			}
			parts = append(parts, partTok.text)
			end = partTok.end
		}
		if len(parts) == 0 {
			return identExpr{name: root, start: tok.start, end: tok.end}, nil
		}
		return traversalExpr{root: root, parts: parts, start: tok.start, end: end}, nil
	case tokenLBracket:
		start := p.next().start
		items := []expr{}
		for p.peek().kind != tokenRBracket && p.peek().kind != tokenEOF {
			item, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			items = append(items, item)
			if p.peek().kind == tokenComma {
				p.next()
				continue
			}
			break
		}
		endTok, err := p.expect(tokenRBracket, "Argument or block definition required", "An argument or block definition is required here.")
		if err != nil {
			return nil, err
		}
		return listExpr{items: items, start: start, end: endTok.end}, nil
	default:
		return nil, &hclDiag{
			path:    p.path,
			start:   tok.start,
			end:     tok.end,
			summary: "Argument or block definition required",
			detail:  "An argument or block definition is required here.",
		}
	}
}

type evalScope struct {
	path   string
	stage  string
	env    string
	vars   map[string]miniValue
	locals map[string]miniValue
}

func evalMiniExpr(expression expr, scope evalScope) (miniValue, error) {
	switch e := expression.(type) {
	case stringExpr:
		return evalMiniString(e, scope)
	case identExpr:
		switch e.name {
		case "true":
			return miniValue{kind: valueBool, b: true}, nil
		case "false":
			return miniValue{kind: valueBool, b: false}, nil
		default:
			return miniValue{kind: valueString, s: e.name}, nil
		}
	case traversalExpr:
		return evalTraversal(e, scope)
	case callExpr:
		return evalCall(e, scope)
	case listExpr:
		items := make([]miniValue, 0, len(e.items))
		for _, item := range e.items {
			v, err := evalMiniExpr(item, scope)
			if err != nil {
				return miniValue{}, err
			}
			items = append(items, v)
		}
		return miniValue{kind: valueList, list: items}, nil
	default:
		return miniValue{}, fmt.Errorf("unsupported expression")
	}
}

func evalMiniString(e stringExpr, scope evalScope) (miniValue, error) {
	value := e.value
	for {
		start := strings.Index(value, "${")
		if start == -1 {
			break
		}
		end := strings.Index(value[start+2:], "}")
		if end == -1 {
			break
		}
		inner := value[start+2 : start+2+end]
		parser, err := newHCLParser(scope.path, "v = "+inner)
		if err != nil {
			return miniValue{}, err
		}
		file, err := parser.parseFile()
		if err != nil {
			return miniValue{}, err
		}
		sub, err := evalMiniExpr(file.blocks[0].attrs[0].expr, scope)
		if err != nil {
			return miniValue{}, err
		}
		value = value[:start] + sub.String() + value[start+2+end+1:]
	}
	return miniValue{kind: valueString, s: value}, nil
}

func evalTraversal(e traversalExpr, scope evalScope) (miniValue, error) {
	var current map[string]miniValue
	switch e.root {
	case "var":
		current = scope.vars
	case "local":
		current = scope.locals
		if current == nil {
			summary := "Unknown variable"
			if scope.stage == "env" {
				summary = "Unknown local"
			}
			return miniValue{}, &hclDiag{
				path:    scope.path,
				start:   e.start,
				end:     e.end,
				summary: summary,
				detail:  `There is no variable named "local".`,
			}
		}
	case "atlas":
		current = map[string]miniValue{"env": {kind: valueString, s: scope.env}}
	default:
		return miniValue{}, &hclDiag{
			path:    scope.path,
			start:   e.start,
			end:     e.end,
			summary: "Unknown variable",
			detail:  fmt.Sprintf(`There is no variable named %q.`, e.root),
		}
	}
	val, ok := current[e.parts[0]]
	if !ok {
		return miniValue{}, &hclDiag{
			path:    scope.path,
			start:   e.start,
			end:     e.end,
			summary: "Unsupported attribute",
			detail:  fmt.Sprintf(`This object does not have an attribute named %q.`, e.parts[0]),
		}
	}
	if len(e.parts) > 1 {
		return miniValue{}, &hclDiag{
			path:    scope.path,
			start:   e.start,
			end:     e.end,
			summary: "Unsupported attribute",
			detail:  fmt.Sprintf(`This object does not have an attribute named %q.`, e.parts[1]),
		}
	}
	return val, nil
}

func evalCall(e callExpr, scope evalScope) (miniValue, error) {
	if e.name != "getenv" {
		return miniValue{}, &hclDiag{
			path:    scope.path,
			start:   e.start,
			end:     e.end,
			summary: "Call to unknown function",
			detail:  fmt.Sprintf(`There is no function named %q.`, e.name),
		}
	}
	if len(e.args) == 0 {
		return miniValue{}, &hclDiag{
			path:    scope.path,
			start:   e.start,
			end:     e.end,
			summary: "Not enough function arguments",
			detail:  `Function "getenv" expects 1 argument(s). Missing value for "key".`,
		}
	}
	if len(e.args) > 1 {
		start, end := e.args[1].span()
		return miniValue{}, &hclDiag{
			path:    scope.path,
			start:   start,
			end:     end,
			summary: "Too many function arguments",
			detail:  `Function "getenv" expects only 1 argument(s).`,
		}
	}
	arg, err := evalMiniExpr(e.args[0], scope)
	if err != nil {
		return miniValue{}, err
	}
	return miniValue{kind: valueString, s: getenv(arg.String())}, nil
}

func getenv(key string) string {
	return strings.TrimRightFunc(strings.TrimLeftFunc(strings.TrimSpace(" "+strings.TrimSpace(key)), unicode.IsSpace), unicode.IsSpace)
}

func miniValueToString(v miniValue) string {
	return v.String()
}

func formatHCLBytes(data []byte) []byte {
	lines := strings.Split(string(data), "\n")
	var out []string
	indent := 0
	for _, raw := range lines {
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" {
			continue
		}
		formatted := formatHCLLine(trimmed)
		if strings.HasPrefix(formatted, "}") && indent >= 2 {
			indent -= 2
		}
		out = append(out, strings.Repeat(" ", indent)+formatted)
		if openCountForIndent(formatted) > 0 {
			indent += 2 * openCountForIndent(formatted)
		}
	}
	var buf bytes.Buffer
	for i, line := range out {
		buf.WriteString(line)
		if i == len(out)-1 {
			buf.WriteByte('\n')
			break
		}
		buf.WriteByte('\n')
		if strings.HasSuffix(line, "}") {
			next := strings.TrimSpace(out[i+1])
			if next != "" && !strings.HasPrefix(next, "}") && !strings.HasPrefix(next, "  ") && !strings.HasPrefix(next, " ") {
				buf.WriteByte('\n')
			}
		}
	}
	return buf.Bytes()
}

func formatHCLLine(line string) string {
	tokens, err := lexAllHCL(line, false)
	if err != nil {
		return strings.TrimSpace(line)
	}
	tokens = tokens[:len(tokens)-1]
	var b strings.Builder
	for i, tok := range tokens {
		prev := prevToken(tokens, i)
		next := nextToken(tokens, i)
		switch tok.kind {
		case tokenEqual:
			trimTrailingSpaces(&b)
			b.WriteString(" = ")
		case tokenComma:
			trimTrailingSpaces(&b)
			b.WriteString(", ")
		case tokenDot:
			trimTrailingSpaces(&b)
			b.WriteString(".")
		case tokenLParen:
			trimTrailingSpaces(&b)
			b.WriteString("(")
		case tokenRParen:
			trimTrailingSpaces(&b)
			b.WriteString(")")
		case tokenLBracket:
			if needsWordSpace(prev, tok) {
				b.WriteByte(' ')
			}
			b.WriteString("[")
		case tokenRBracket:
			trimTrailingSpaces(&b)
			b.WriteString("]")
		case tokenLBrace:
			if needsWordSpace(prev, tok) {
				b.WriteByte(' ')
			}
			b.WriteString("{")
			if next.kind == tokenLBrace {
				b.WriteByte(' ')
			}
		case tokenRBrace:
			trimTrailingSpaces(&b)
			if prev.kind == tokenLBrace {
				b.WriteString("}")
			} else {
				b.WriteString("}")
			}
		default:
			if needsWordSpace(prev, tok) {
				b.WriteByte(' ')
			}
			if tok.kind == tokenString {
				b.WriteString(strconv.Quote(tok.text))
			} else {
				b.WriteString(tok.text)
			}
		}
	}
	return strings.TrimSpace(b.String())
}

func prevToken(tokens []hclToken, i int) hclToken {
	if i == 0 {
		return hclToken{}
	}
	return tokens[i-1]
}

func nextToken(tokens []hclToken, i int) hclToken {
	if i+1 >= len(tokens) {
		return hclToken{}
	}
	return tokens[i+1]
}

func needsWordSpace(prev, tok hclToken) bool {
	if prev.kind == 0 {
		return false
	}
	if prev.kind == tokenEqual || prev.kind == tokenComma || prev.kind == tokenLBracket || prev.kind == tokenLParen || prev.kind == tokenDot {
		return false
	}
	if tok.kind == tokenComma || tok.kind == tokenDot || tok.kind == tokenRBracket || tok.kind == tokenRParen || tok.kind == tokenRBrace {
		return false
	}
	return true
}

func trimTrailingSpaces(b *strings.Builder) {
	s := b.String()
	s = strings.TrimRight(s, " ")
	b.Reset()
	b.WriteString(s)
}

func openCountForIndent(line string) int {
	count := 0
	for i := 0; i < len(line); i++ {
		if line[i] == '{' {
			if i+1 < len(line) && line[i+1] == ' ' && i+2 < len(line) && line[i+2] == '{' {
				continue
			}
			count++
		}
	}
	return count
}

