/workspace/config.go.content:
package main

import (
	"fmt"
	"net/url"
	"os"
)

type globalFlags struct {
	configURL string
	env       string
	vars      map[string]string
}

type envConfig struct {
	values map[string]miniValue
}

func defaultGlobals() globalFlags {
	return globalFlags{
		configURL: "file://atlas.hcl",
		vars:      map[string]string{},
	}
}

func parseConfigPath(raw string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return "", err
	}
	if u.Scheme == "" {
		return "", fmt.Errorf("missing scheme for config file. Did you mean %s?", "file://"+raw)
	}
	if u.Scheme != "file" {
		return "", fmt.Errorf("unsupported config file scheme %q", u.Scheme)
	}
	return u.Host + u.Path, nil
}

func parseDirURL(raw string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return "", err
	}
	if u.Scheme == "" {
		return "", fmt.Errorf("missing scheme for dir url. Did you mean %q? ", "file://"+raw)
	}
	if u.Scheme != "file" {
		return "", fmt.Errorf("unsupported dir url scheme %q", u.Scheme)
	}
	return u.Host + u.Path, nil
}

func loadEnvConfig(globals globalFlags) (*envConfig, error) {
	path, err := parseConfigPath(globals.configURL)
	if err != nil {
		return nil, err
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("config file %q was not found: %w", path, err)
	}
	parser, err := newHCLParser(path, string(data))
	if err != nil {
		return nil, err
	}
	file, err := parser.parseFile()
	if err != nil {
		return nil, err
	}
	varBlocks := []blockExpr{}
	localAttrs := []attrExpr{}
	var envBlock *blockExpr
	for i := range file.blocks {
		block := &file.blocks[i]
		switch block.typ {
		case "variable":
			varBlocks = append(varBlocks, *block)
		case "locals":
			localAttrs = append(localAttrs, block.attrs...)
		case "env":
			if block.label == globals.env {
				envBlock = block
			}
		}
	}
	if envBlock == nil {
		return nil, fmt.Errorf("env %q not defined in config file", globals.env)
	}
	vars := map[string]miniValue{}
	for _, block := range varBlocks {
		name := block.label
		if value, ok := globals.vars[name]; ok {
			vars[name] = miniValue{kind: valueString, s: value}
			continue
		}
		var defaultExpr expr
		for _, attr := range block.attrs {
			if attr.name == "default" {
				defaultExpr = attr.expr
				break
			}
		}
		if defaultExpr == nil {
			return nil, fmt.Errorf("missing value for required variable %q", name)
		}
		value, err := evalMiniExpr(defaultExpr, evalScope{path: path, stage: "var", env: globals.env, vars: vars})
		if err != nil {
			return nil, err
		}
		vars[name] = value
	}
	locals := map[string]miniValue{}
	for _, attr := range localAttrs {
		scope := evalScope{path: path, stage: "locals", env: globals.env, vars: vars}
		if len(locals) > 0 {
			scope.locals = locals
		}
		value, err := evalMiniExpr(attr.expr, scope)
		if err != nil {
			return nil, err
		}
		locals[attr.name] = value
	}
	values := map[string]miniValue{}
	for _, attr := range envBlock.attrs {
		scope := evalScope{path: path, stage: "env", env: globals.env, vars: vars}
		if len(locals) > 0 {
			scope.locals = locals
		}
		value, err := evalMiniExpr(attr.expr, scope)
		if err != nil {
			return nil, err
		}
		values[attr.name] = value
	}
	return &envConfig{values: values}, nil
}

func valueAsString(values map[string]miniValue, key string) string {
	value, ok := values[key]
	if !ok {
		return ""
	}
	if value.kind != valueString {
		return ""
	}
	return value.s
}

